local ED={ID,Qr,CV}
local ex=Kd.string
if type(ex)=="table" then
ED[#ED+1]=ex.char ED[#ED+1]=ex.byte ED[#ED+1]=ex.sub ED[#ED+1]=ex.rep ED[#ED+1]=ex.len
